import pytest
from fastapi import APIRouter, FastAPI, Request
from fastapi.routing import APIRoute
from fastapi.testclient import TestClient


class AuditedRoute(APIRoute):
    accessed: list[str] = []

    def get_route_handler(self):
        original_handler = super().get_route_handler()

        async def audited_handler(request: Request):
            AuditedRoute.accessed.append(request.url.path)
            return await original_handler(request)

        return audited_handler


@pytest.fixture(autouse=True)
def clear_accessed():
    AuditedRoute.accessed.clear()
    yield
    AuditedRoute.accessed.clear()


def test_route_class_map():
    router = APIRouter(route_class_map={"POST": AuditedRoute})

    @router.get("/items")
    def get_items():
        return {"method": "GET"}

    @router.post("/items")
    def post_items():
        return {"method": "POST"}

    app = FastAPI()
    app.include_router(router)
    client = TestClient(app)

    response = client.get("/items")
    assert response.status_code == 200
    assert response.json() == {"method": "GET"}
    assert AuditedRoute.accessed == []

    response = client.post("/items")
    assert response.status_code == 200
    assert response.json() == {"method": "POST"}
    assert AuditedRoute.accessed == ["/items"]


@pytest.mark.parametrize("methods", [["post"], None])
def test_method_normalization_and_default(methods):
    method = "POST" if methods else "GET"
    router = APIRouter(route_class_map={method: AuditedRoute})
    router.add_api_route("/items", lambda: {}, methods=methods)
    client = TestClient(router)

    assert client.request(method, "/items").status_code == 200
    assert AuditedRoute.accessed == ["/items"]


@pytest.mark.parametrize("route_class_map", [None, {}, {"POST": APIRoute}])
def test_fallback_to_route_class(route_class_map):
    router = APIRouter(route_class=AuditedRoute, route_class_map=route_class_map)
    router.add_api_route("/items", lambda: {})
    client = TestClient(router)

    assert client.get("/items").status_code == 200
    assert AuditedRoute.accessed == ["/items"]


def test_explicit_route_class_override():
    router = APIRouter(route_class_map={"POST": AuditedRoute})
    router.add_api_route(
        "/items", lambda: {}, methods=["POST"], route_class_override=APIRoute
    )
    client = TestClient(router)

    assert client.post("/items").status_code == 200
    assert AuditedRoute.accessed == []


@pytest.mark.parametrize("methods", [["get", "post"], {"GET", "POST"}])
def test_multiple_methods(methods):
    router = APIRouter(route_class_map={"POST": AuditedRoute})
    router.add_api_route("/items", lambda: {}, methods=methods)
    app = FastAPI()
    app.include_router(router)
    client = TestClient(app)

    assert client.get("/items").status_code == 200
    assert AuditedRoute.accessed == []
    assert client.post("/items").status_code == 200
    assert AuditedRoute.accessed == ["/items"]
    assert set(app.openapi()["paths"]["/items"]) == {"get", "post"}

